import {STAGES,money,compactMoney,dateKey as localDateKey,offsetDate} from './model.js';
import {request,setCsrf,recordPayload,resource,stageCode} from './api.js';
const $ = s => document.querySelector(s);
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0 M12 10v4 M10 12h4',board:'M3 4h18v16H3z M9 4v16 M15 4v16',check:'M9 11l3 3L22 4 M21 12v8H3V4h12',chart:'M3 3v18h18 M7 15v-4 M12 15V7 M17 15V5',book:'M12 5v16 M12 5C8 2 4 3 2 4v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-3-1-7-2-10 1',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',up:'M7 17L17 7 M7 7h10v10',download:'M12 3v12 M7 10l5 5 5-5 M5 16v5h14v-5',clock:'M12 8v4l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',more:'M5 12h.01 M12 12h.01 M19 12h.01',close:'M6 6l12 12 M18 6L6 18',mail:'M3 5h18v14H3z M3 5l9 7 9-7',phone:'M5 3h4l2 5-3 2a16 16 0 0 0 6 6l2-3 5 2v4c0 2-3 2-5 1C9 17 4 12 3 5c0-1 0-2 2-2',building:'M4 21V3h12v18 M16 9h4v12 M8 7h4 M8 11h4 M8 15h4 M2 21h20',wallet:'M3 5h16v4 M3 5v14h18V9H3 M16 14h2',menu:'M3 6h18 M3 12h18 M3 18h18',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',edit:'M15 5l4 4 M4 20l4-1L21 6l-4-4L4 15z',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.grid}"/></svg>`;
let data=null, busy=false, refreshNumber=0;
const dateKey=()=>data?.analytics?.today||localDateKey();
const stats=()=>data.analytics;
const roleLabel=role=>({sales:'Sales Representative',manager:'Sales Manager',admin:'Admin'}[role]||role);

let page=location.hash.slice(1)||'dashboard',query='',filter='Semua',days=30,taskFilter='Aktif',mobile=false;
const nav=[['dashboard','grid','Dashboard'],['companies','building','Perusahaan'],['contacts','people','Kontak'],['leads','target','Leads'],['pipeline','board','Pipeline'],['tasks','check','Tugas'],['reports','chart','Laporan']];
const titles={companies:['Perusahaan','Kelola akun bisnis dan hubungan di dalamnya.'],users:['Pengguna','Kelola akses dan anggota workspace.'],dashboard:['Dashboard','Gambaran bisnis Anda, dalam satu tempat.'],contacts:['Kontak','Bangun hubungan yang lebih baik dengan setiap klien.'],leads:['Leads','Dari percakapan pertama menjadi peluang baru.'],pipeline:['Pipeline penjualan','Setiap peluang punya langkah berikutnya.'],tasks:['Tugas & follow-up','Jaga percakapan berjalan. Jangan lewatkan kesempatan.'],reports:['Laporan penjualan','Pahami angka di balik perkembangan bisnis Anda.'],guide:['Panduan CRM','Belajar konsepnya, lalu praktikkan langsung.'],settings:['Pengaturan','Kelola workspace dan data demo Anda.']};
async function refresh(){
  const number=++refreshNumber;
  const next=await request(`/workspace?days=${days}`);
  if(number!==refreshNumber)return;
  data=next;render();
}
async function mutate(fn,message,{close=true}={}){
  if(busy)return;busy=true;
  let committed=false;
  const buttons=[...document.querySelectorAll('dialog button[type="submit"],dialog #confirm')];buttons.forEach(b=>b.disabled=true);
  try{await fn();committed=true;if(close)$('#modal').close();await refresh();if(message)toast(message);}
  catch(error){if(error.status===401){$('#modal').close();showLogin('Sesi berakhir. Silakan masuk kembali.');}else{if(data)render();toast(committed?'Perubahan tersimpan, tetapi data terbaru belum dimuat. Muat ulang halaman.':error.message);}}
  finally{busy=false;buttons.forEach(b=>b.disabled=false);}
}
async function bootstrap(){
  $('#app').innerHTML='<div class="app-loading" role="status">Menghubungkan ke CRM…</div>';
  try{const session=await request('/auth/me');setCsrf(session.csrf);await refresh();}
  catch(error){if(error.status===401)showLogin();else showConnectionError(error.message);}
}
function showConnectionError(message){$('#app').innerHTML=`<section class="login-panel"><h1>CRM belum terhubung</h1><p>${esc(message)}</p><button class="btn primary" id="retry">Coba lagi</button></section>`;$('#retry').onclick=bootstrap;}
function showLogin(message=''){
  data=null;mobile=false;query='';filter='Semua';setCsrf('');
  $('#app').innerHTML=`<div class="login-shell"><section class="login-story"><a class="brand"><span class="brand-mark">${icon('grid')}</span><span>crm<span class="brand-light">business</span><small>SALES WORKSPACE</small></span></a><h1>Kenali pelanggan.<br>Temukan peluang.<br><span>Tumbuh bersama.</span></h1><p>Workspace CRM untuk mengelola relasi dan proses penjualan bersama tim Anda.</p></section><section class="login-panel"><span class="eyebrow">WELCOME TO YOUR WORKSPACE</span><h1>Selamat datang kembali.</h1><p>Masuk untuk melanjutkan hubungan yang berarti.</p><form id="login-form"><label>Email<input name="email" type="email" autocomplete="username" required placeholder="nama@perusahaan.com"></label><label>Password<input name="password" type="password" autocomplete="current-password" required maxlength="256"></label><p class="login-error" role="alert">${esc(message)}</p><button class="btn primary" type="submit">Masuk ke workspace ${icon('arrow')}</button></form><div id="demo-login"></div></section></div>`;
  request('/auth/demo').then(info=>{if(info.available)$('#demo-login').innerHTML=`<div class="demo-login-note"><strong>Akun demo · data fiktif</strong><p>Password demo: <code>PortfolioDemo!2026</code><br>Jangan gunakan password ini pada sistem sungguhan.</p><div>${[['rep','Sales Rep'],['manager','Manager'],['admin','Admin']].map(([key,label])=>`<button class="btn small" data-demo-email="${key}@crm-demo.example">${label}</button>`).join('')}</div></div>`;}).catch(()=>{});
  $('#login-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;$('.login-error').textContent='';try{const result=await request('/auth/login',{method:'POST',body:Object.fromEntries(new FormData(e.target))});setCsrf(result.csrf);await refresh();}catch(error){if($('.login-error'))$('.login-error').textContent=error.message;}finally{button.disabled=false;}};
}

function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function contact(id){return data.contacts.find(c=>c.id===id)||{name:'Tanpa kontak',company:'—'};}
const initials=name=>String(name).trim().split(/\s+/).slice(0,2).map(w=>w[0]||'').join('').toUpperCase();
function avatar(c,i=0){return `<span class="avatar tone-${i%5}">${esc(initials(c.name))}</span>`;}
function badge(text){return `<span class="badge badge-${['Berhasil','Dikonversi','Selesai'].includes(text)?'green':['Gagal','Tinggi','Tidak cocok'].includes(text)?'red':['Proposal','Kualifikasi','Sedang'].includes(text)?'amber':['Negosiasi','Dihubungi'].includes(text)?'purple':'blue'}">${esc(text)}</span>`;}
function fmtDate(s){return s?new Date(s+'T12:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'short'}):'—';}
function matches(...values){return values.some(v=>String(v||'').toLowerCase().includes(query.toLowerCase()));}
function empty(title,description,action=''){return `<div class="empty">${icon('search')}<h3>${title}</h3><p>${description}</p>${action}</div>`;}
function actionButton(kind,label){return `<button class="btn primary" data-action="new" data-kind="${kind}">${icon('plus')}${label}</button>`;}
function dateSelect(){return `<select id="period" aria-label="Periode laporan">${[30,90,365].map(d=>`<option value="${d}" ${days===d?'selected':''}>${d} hari terakhir</option>`).join('')}</select>`;}
function render(){
  if(!data)return;
  if(!titles[page]||(page==='users'&&data.user.role!=='admin'))page='dashboard';
  const [title,sub]=titles[page];
  $('#app').innerHTML=`<aside class="sidebar ${mobile?'open':''}"><a class="brand" href="#dashboard"><span class="brand-mark">${icon('grid')}</span><span>crm<span class="brand-light">business</span><small>SALES WORKSPACE</small></span></a><button class="workspace" data-action="navigate" data-page="settings"><span class="workspace-icon">N</span><span><strong>${esc(data.workspace)}</strong><small>${esc(roleLabel(data.user.role))}</small></span><span class="chevron">⌄</span></button><p class="nav-label">WORKSPACE</p><nav aria-label="Navigasi utama">${nav.map(([key,ic,label])=>`<a href="#${key}" class="nav-item ${page===key?'active':''}">${icon(ic)}<span>${label}</span>${key==='tasks'?`<span class="nav-count">${data.tasks.filter(t=>!t.done).length}</span>`:''}</a>`).join('')}</nav>${data.user.role==='admin'?`<a class="nav-item ${page==='users'?'active':''}" href="#users">${icon("people")}Pengguna</a>`:''}<p class="nav-label resources-label">RESOURCES</p><a class="nav-item ${page==='guide'?'active':''}" href="#guide">${icon('book')}Panduan CRM<span class="tiny-new">NEW</span></a><a class="nav-item ${page==='settings'?'active':''}" href="#settings">${icon('settings')}Pengaturan</a><div class="sidebar-bottom"><div class="demo-card">${icon('spark')}<strong>Your next big deal starts here.</strong><p>Pelajari alurnya. Bangun relasinya.</p><a href="#guide">Kenali CRM ${icon('arrow')}</a></div><div class="profile"><span class="avatar profile-avatar">NS</span><div><strong>${esc(data.user.name)}</strong><small>${esc(roleLabel(data.user.role))}</small></div><button class="icon-btn logout-button" data-action="logout" aria-label="Keluar">${icon("arrow")}</button></div></div></aside>${mobile?'<button class="sidebar-backdrop" data-action="menu" aria-label="Tutup navigasi"></button>':''}<div class="main-shell"><header class="topbar"><div class="crumb"><button class="icon-btn mobile-toggle" data-action="menu" aria-label="Buka navigasi">${icon('menu')}</button><span>Workspace</span><span class="crumb-slash">/</span><strong>${title}</strong></div><div class="topbar-right"><span class="demo-pill"><span></span>Portfolio demo</span><a class="help-button" href="#guide" aria-label="Buka panduan CRM">?</a><span class="avatar mini">NS</span></div></header><main><div class="page-heading"><div><div class="eyebrow">${page==='dashboard'?'YOUR BUSINESS AT A GLANCE':'NUSANTARA SALES WORKSPACE'}</div><h1>${title}${page==='dashboard'?'<span class="hello-dot">.</span>':''}</h1><p>${sub}</p></div><div class="heading-actions">${['dashboard','reports'].includes(page)?dateSelect():''}${page==='dashboard'||page==='pipeline'?actionButton('deals','Tambah deal'):page==='companies'?actionButton('companies','Tambah perusahaan'):page==='users'?actionButton('users','Tambah pengguna'):page==='contacts'?actionButton('contacts','Tambah kontak'):page==='leads'?actionButton('leads','Tambah lead'):page==='tasks'?actionButton('tasks','Tambah tugas'):''}</div></div><div id="page-content">${({dashboard,companies:companiesPage,users:usersPage,contacts:contactsPage,leads:leadsPage,pipeline:pipelinePage,tasks:tasksPage,reports:reportsPage,guide:guidePage,settings:settingsPage}[page])()}</div><footer><span>CRM Business <span class="footer-dot">·</span> Made for meaningful relationships</span><span>${icon('shield')} PostgreSQL · akses sesuai role</span></footer></main></div>`;
  bindPage();
  updateSidebarAccessibility();
}
function updateSidebarAccessibility(){const sidebar=$('.sidebar');if(!sidebar)return;const hidden=window.matchMedia('(max-width:700px)').matches&&!mobile;sidebar.inert=hidden;sidebar.setAttribute('aria-hidden',String(hidden));}
window.addEventListener('resize',updateSidebarAccessibility);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&mobile&&!$('#modal').open){mobile=false;render();$('.mobile-toggle')?.focus();}});
function metrics(){const s=stats();return `<div class="metrics">${[
  ['wallet','Deal berhasil',compactMoney(s.won),`${s.wonCount} deal dalam ${days} hari`,'green'],
  ['board','Nilai pipeline',compactMoney(s.pipeline),`${s.activeCount} peluang penjualan aktif`,'blue'],
  ['people','Total kontak',s.contactCount,`${data.companies.length} perusahaan dalam akses Anda`,'purple'],
  ['target','Win rate',`${s.winRate}%`,`${s.wonCount} berhasil dari ${s.closedCount} deal ditutup`,'amber']
].map(([ic,label,value,hint,tone])=>`<section class="metric"><div class="metric-top"><span>${label}</span><span class="metric-icon ${tone}">${icon(ic)}</span></div><strong>${value}</strong><div class="metric-hint">${icon(tone==='green'?'up':'clock')} ${hint}</div></section>`).join('')}</div>`;}
function chart(){
  const now=new Date();const months=Array.from({length:6},(_,i)=>new Date(now.getFullYear(),now.getMonth()-5+i,1));
  const values=data.analytics.months.map(m=>m.value);
  months.splice(0,months.length,...data.analytics.months.map(m=>new Date(m.month+'-01T12:00:00')));
  const max=Math.max(...values,10000000);const points=values.map((v,i)=>[52+i*106,175-v/max*140]);
  const line=points.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');
  return `<div class="chart-wrap"><svg class="revenue-chart" viewBox="0 0 650 222" role="img" aria-label="Grafik nilai deal berhasil selama enam bulan"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#3b82f6" stop-opacity=".17"/><stop offset="100%" stop-color="#3b82f6" stop-opacity="0"/></linearGradient></defs>${[0,.5,1].map(r=>`<line x1="52" y1="${175-r*140}" x2="610" y2="${175-r*140}" stroke="#e9edf3" stroke-dasharray="4 5"/><text x="4" y="${180-r*140}" fill="#909bad" font-size="11">${r?Math.round(max*r/1e6)+' jt':'0'}</text>`).join('')}<path d="${line} L582,175 L52,175 Z" fill="url(#area)"/><path d="${line}" fill="none" stroke="#3b82f6" stroke-width="3" stroke-linejoin="round"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="white" stroke="#3b82f6" stroke-width="2"><title>${months[i].toLocaleDateString('id-ID',{month:'long'})}: ${money(values[i])}</title></circle><text x="${x}" y="211" text-anchor="middle" fill="#8792a5" font-size="12">${months[i].toLocaleDateString('id-ID',{month:'short'})}</text>`).join('')}</svg></div>`;
}
function stageSummary(){const active=STAGES.slice(0,4);const total=data.analytics.pipeline||1;return `<div class="stage-summary">${active.map((st,i)=>{const item=data.analytics.stageValues[st];return `<div><div class="stage-row"><span><i class="stage-dot s${i}"></i>${st}<small>${item.count}</small></span><strong>${compactMoney(item.value)}</strong></div><div class="progress"><span class="s${i}" style="width:${item.value/total*100}%"></span></div></div>`;}).join('')}</div>`;}
function riskSummary(){const a=data.analytics;return `<div class="info-strip">${icon('clock')}<span><strong>${a.overdueTasks} follow-up terlewat</strong> · ${a.atRiskCount} peluang At Risk (tanpa follow-up ${data.risk_days} hari). Cakupan: ${esc(data.user.role==='sales'?'milik/ditugaskan kepada Anda':data.user.role==='manager'?'tim '+data.user.team:'seluruh sistem')}.</span></div>`;}
function managerAnalytics(){if(data.user.role==='sales')return '';const a=data.analytics;return `<section class="panel team-analytics"><div class="panel-heading"><div><h2>Performa ${data.user.role==='manager'?'tim':'sistem'}</h2><p>Conversion rate ${a.conversionRate}% · rata-rata sales cycle ${a.averageSalesCycle} hari</p></div></div><div class="table-wrap"><table><thead><tr><th>SALES REP</th><th>PIPELINE AKTIF</th><th>DEAL BERHASIL</th><th>PELUANG AKTIF</th></tr></thead><tbody>${a.byRep.map(r=>`<tr><td>${esc(r.name)}</td><td>${money(r.pipeline)}</td><td>${money(r.won)}</td><td>${r.open}</td></tr>`).join('')}</tbody></table></div></section>`;}
function recentActivity(){return `<section class="panel team-analytics"><div class="panel-heading"><div><h2>Aktivitas terbaru</h2><p>Audit dalam cakupan akses Anda · klik untuk melihat detail</p></div><a href="#reports" class="text-link">Lihat riwayat ${icon('arrow')}</a></div><div class="activity-list">${data.activities.slice(0,5).map(a=>`<div>${icon('clock')}<button class="audit-link" data-action="audit" data-id="${esc(a.id)}">${esc(a.text)}</button><small>${new Date(a.date).toLocaleDateString('id-ID',{day:'numeric',month:'short'})}</small></div>`).join('')||'<p class="muted">Belum ada aktivitas.</p>'}</div></section>`;}

function dashboard(){const pending=data.tasks.filter(t=>!t.done).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4);return `${metrics()}${riskSummary()}<div class="dashboard-middle"><section class="panel revenue-panel"><div class="panel-heading"><div><h2>Performa penjualan</h2><p>Nilai deal berhasil · 6 bulan terakhir</p></div><span class="legend"><i></i>Deal berhasil</span></div>${chart()}</section><section class="panel"><div class="panel-heading"><div><h2>Pipeline overview</h2><p>Peluang yang sedang berjalan</p></div><a href="#pipeline" class="icon-link" aria-label="Lihat pipeline">${icon('up')}</a></div>${stageSummary()}<a href="#pipeline" class="panel-bottom-link">Lihat semua peluang ${icon('arrow')}</a></section></div><div class="dashboard-bottom"><section class="panel deal-panel"><div class="panel-heading"><div><h2>Peluang terbaru <span class="count-label">${data.deals.length}</span></h2><p>Satu langkah lebih dekat ke deal berikutnya</p></div><a href="#pipeline" class="text-link">Lihat semua ${icon('arrow')}</a></div>${dealTable(data.deals.slice().sort((a,b)=>b.created.localeCompare(a.created)).slice(0,4))}</section><section class="panel follow-panel"><div class="panel-heading"><div><h2>Agenda follow-up</h2><p>${data.tasks.filter(t=>!t.done&&t.date===dateKey()).length} tugas hari ini · tetap terhubung</p></div><a href="#tasks" class="icon-link" aria-label="Lihat semua tugas">${icon('up')}</a></div>${pending.length?pending.map(taskItem).join(''):empty('Semua beres!','Tidak ada follow-up yang tertunda.')}<a href="#tasks" class="panel-bottom-link">Lihat semua tugas ${icon('arrow')}</a></section></div>${managerAnalytics()}${recentActivity()}<div class="learn-banner"><span class="learn-icon">${icon('book')}</span><div><strong>Baru mengenal CRM? Mulai dari satu hubungan.</strong><p>Kenali leads, contacts, dan deals lewat panduan singkat kami.</p></div><a href="#guide">Buka panduan ${icon('arrow')}</a></div>`;}
function dealTable(list){return list.length?`<div class="table-wrap"><table><thead><tr><th>PELUANG / PERUSAHAAN</th><th>NILAI DEAL</th><th>TAHAP</th><th aria-label="Aksi"></th></tr></thead><tbody>${list.map((d,i)=>`<tr><td><button class="row-person" data-action="edit" data-kind="deals" data-id="${esc(d.id)}">${avatar(contact(d.contact),i)}<span><strong>${esc(d.title)}</strong><small>${esc(contact(d.contact).company)}</small></span></button></td><td class="numeric">${money(d.value)}</td><td>${badge(d.stage)}</td><td><button class="icon-btn" data-action="edit" data-kind="deals" data-id="${esc(d.id)}" aria-label="Edit ${esc(d.title)}">${icon('more')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada peluang','Tambahkan deal pertama Anda.',actionButton('deals','Tambah deal'));}
function taskItem(t){const overdue=t.overdue;return `<div class="task-item ${t.done?'completed':''}"><input type="checkbox" data-task="${esc(t.id)}" ${t.done?'checked':''} aria-label="Selesaikan ${esc(t.title)}"><button class="task-text" data-action="edit" data-kind="tasks" data-id="${esc(t.id)}"><strong>${esc(t.title)}</strong><small>${esc(contact(t.contact).company)} <span>·</span> <span class="${overdue?'overdue':''}">${t.date===dateKey()?'Hari ini':fmtDate(t.date)}${overdue?' · Terlewat':''}</span></small></button><span class="priority-dot ${t.priority==='Tinggi'?'high':t.priority==='Sedang'?'medium':'low'}" title="Prioritas ${esc(t.priority)}"></span></div>`;}
function toolbar(filters,extra=''){return `<div class="toolbar"><label class="search-box">${icon('search')}<input id="search" type="search" value="${esc(query)}" placeholder="Cari ${page==='contacts'?'nama, perusahaan, email':page==='pipeline'?'peluang atau perusahaan':page==='leads'?'lead atau perusahaan':'tugas atau perusahaan'}…" aria-label="Cari data"></label><div class="toolbar-right">${filters?`<select id="filter" aria-label="Filter data">${filters.map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select>`:''}${extra}</div></div>`;}
function contactsPage(){const list=data.contacts.filter(c=>matches(c.name,c.company,c.email));return `${toolbar(null,`<button class="btn" data-action="csv">${icon('download')}Ekspor CSV</button>`)}<section class="panel"><div class="panel-heading"><h2>Semua kontak <span class="count-label">${list.length}</span></h2><span class="muted">${new Set(data.contacts.map(c=>c.company).filter(Boolean)).size} perusahaan</span></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>NAMA KONTAK</th><th>PERUSAHAAN</th><th>EMAIL</th><th>TELEPON</th><th>DEAL</th><th></th></tr></thead><tbody>${list.map((c,i)=>`<tr><td><button class="row-person" data-action="edit" data-kind="contacts" data-id="${esc(c.id)}">${avatar(c,i)}<span><strong>${esc(c.name)}</strong><small>${esc(c.role||'Kontak bisnis')}</small></span></button></td><td>${esc(c.company||'—')}</td><td class="muted">${esc(c.email||'—')}</td><td class="muted">${esc(c.phone||'—')}</td><td><span class="count-label">${data.deals.filter(d=>d.contact===c.id).length}</span></td><td><button class="icon-btn" data-action="edit" data-kind="contacts" data-id="${esc(c.id)}" aria-label="Edit ${esc(c.name)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Tidak ada kontak','Coba kata pencarian lain atau tambahkan kontak baru.',actionButton('contacts','Tambah kontak'))}</section>`;}
function leadsPage(){const list=data.leads.filter(l=>matches(l.name,l.company,l.email)&&(filter==='Semua'||filter===l.status));return `${toolbar(['Semua','Baru','Dihubungi','Kualifikasi','Dikonversi','Tidak cocok'])}<div class="info-strip">${icon('target')}<span><strong>Lead adalah awal sebuah hubungan.</strong> Setelah kebutuhannya jelas, konversikan menjadi kontak dan peluang penjualan.</span></div><section class="panel"><div class="panel-heading"><h2>Daftar leads <span class="count-label">${list.length}</span></h2></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>CALON KLIEN</th><th>SUMBER</th><th>STATUS</th><th>DITAMBAHKAN</th><th>AKSI</th></tr></thead><tbody>${list.map((l,i)=>`<tr><td><button class="row-person" data-action="edit" data-kind="leads" data-id="${esc(l.id)}">${avatar(l,i)}<span><strong>${esc(l.name)}</strong><small>${esc(l.company)}</small></span></button></td><td>${esc(l.source)}</td><td>${badge(l.status)}</td><td class="muted">${fmtDate(l.created)}</td><td>${l.status==='Dikonversi'?'<span class="muted">Sudah dikonversi</span>':`<button class="btn small" data-action="convert" data-id="${esc(l.id)}">Konversi ${icon('arrow')}</button>`}</td></tr>`).join('')}</tbody></table></div>`:empty('Tidak ada lead','Tambahkan calon pelanggan pertama Anda.',actionButton('leads','Tambah lead'))}</section>`;}
function pipelinePage(){const stages=filter==='Semua'?STAGES:[filter];return `${toolbar(['Semua',...STAGES])}<div class="pipeline-stats"><span><strong>${stats(data).activeCount}</strong> deal aktif</span><span><strong>${compactMoney(stats(data).pipeline)}</strong> nilai pipeline</span><span class="muted">Geser kartu atau ubah tahap di dalam kartu</span></div><div class="kanban">${stages.map(st=>{const list=data.deals.filter(d=>d.stage===st&&matches(d.title,contact(d.contact).company,contact(d.contact).name));return `<section class="kanban-column" data-stage="${st}"><div class="column-heading"><span><i class="stage-dot s${STAGES.indexOf(st)}"></i><strong>${st}</strong><small>${list.length}</small></span><button class="icon-btn" data-action="new" data-kind="deals" data-stage="${st}" aria-label="Tambah deal tahap ${st}">${icon('plus')}</button></div><div class="column-total">${compactMoney(list.reduce((s,d)=>s+d.value,0))}</div><div class="drop-zone">${list.map(d=>`<article class="deal-card" draggable="true" data-deal="${esc(d.id)}"><div class="deal-card-top"><span class="company-label">${esc(contact(d.contact).company)}</span><button class="icon-btn" data-action="edit" data-kind="deals" data-id="${esc(d.id)}" aria-label="Edit ${esc(d.title)}">${icon('more')}</button></div><button class="deal-title" data-action="edit" data-kind="deals" data-id="${esc(d.id)}">${esc(d.title)}</button><strong class="deal-value">${money(d.value)}</strong>${d.at_risk?'<span class="badge badge-red risk-badge">At Risk</span>':''}<div class="deal-card-footer"><span>${avatar(contact(d.contact),STAGES.indexOf(st))}${esc(contact(d.contact).name.split(' ')[0])}</span><span>${icon('clock')}${fmtDate(d.due)}</span></div><small class="owner-label">Owner: ${esc(data.users.find(u=>u.id===d.owner_id)?.name||'Assigned record')}</small><select class="stage-select" data-move="${esc(d.id)}" aria-label="Tahap ${esc(d.title)}">${STAGES.map(s=>`<option ${st===s?'selected':''}>${s}</option>`).join('')}</select></article>`).join('')||'<div class="drop-empty">Belum ada deal<br><small>Tambahkan atau geser kartu ke sini</small></div>'}</div></section>`;}).join('')}</div>`;}
function tasksPage(){const list=data.tasks.filter(t=>matches(t.title,contact(t.contact).company)&&(taskFilter==='Semua'||(taskFilter==='Selesai'?t.done:!t.done))).sort((a,b)=>a.date.localeCompare(b.date));return `${toolbar(null)}<div class="tabs" role="group" aria-label="Filter tugas">${['Aktif','Selesai','Semua'].map(f=>`<button class="${taskFilter===f?'selected':''}" data-action="task-filter" data-filter="${f}">${f}<span>${data.tasks.filter(t=>f==='Semua'||(f==='Selesai'?t.done:!t.done)).length}</span></button>`).join('')}</div><section class="panel task-list"><div class="panel-heading"><div><h2>Langkah berikutnya</h2><p>Tandai tugas ketika follow-up sudah dilakukan.</p></div>${badge(`${data.analytics.overdueTasks} terlewat`)}</div>${list.length?list.map(taskItem).join(''):empty('Agenda bersih','Tidak ada tugas pada filter ini.',actionButton('tasks','Tambah tugas'))}</section>`;}
function reportsPage(){const s=stats();return `${metrics()}${riskSummary()}<div class="dashboard-middle"><section class="panel"><div class="panel-heading"><div><h2>Tren deal berhasil</h2><p>Nilai kontrak, bukan pembayaran yang diterima</p></div></div>${chart()}</section><section class="panel"><div class="panel-heading"><div><h2>Distribusi pipeline</h2><p>Nilai peluang per tahap aktif</p></div></div>${stageSummary()}</section></div><div class="dashboard-bottom"><section class="panel"><div class="panel-heading"><div><h2>Sumber leads</h2><p>Lead dalam cakupan akses Anda</p></div></div><div class="source-list">${Object.keys(data.analytics.sourceCounts).map((src,i)=>`<div class="source-row"><span><i class="stage-dot s${i%4}"></i>${esc(src)}</span><div class="progress"><span class="s${i%4}" style="width:${data.analytics.sourceCounts[src]/Math.max(data.leads.length,1)*100}%"></span></div><strong>${data.analytics.sourceCounts[src]}</strong></div>`).join('')||empty('Belum ada lead','Tambahkan lead untuk melihat sumbernya.')}</div></section><section class="panel"><div class="panel-heading"><h2>Ringkasan ${days} hari</h2></div><dl class="report-summary"><div><dt>Deal berhasil</dt><dd>${s.wonCount}</dd></div><div><dt>Deal gagal</dt><dd>${s.closedCount-s.wonCount}</dd></div><div><dt>Rata-rata nilai deal berhasil</dt><dd>${compactMoney(s.wonCount?s.won/s.wonCount:0)}</dd></div><div><dt>Win rate</dt><dd>${s.winRate}%</dd></div></dl></section></div><section class="panel"><div class="panel-heading"><h2>Aktivitas terbaru</h2></div><div class="activity-list">${data.activities.slice(0,8).map(a=>`<div>${icon('clock')}<button class="audit-link" data-action="audit" data-id="${esc(a.id)}">${esc(a.text)}</button><small>${new Date(a.date).toLocaleDateString('id-ID',{day:'numeric',month:'short'})}</small></div>`).join('')||'<p class="muted">Belum ada aktivitas.</p>'}</div></section>`;}
function guidePage(){return `<section class="guide-hero"><span class="eyebrow">RELATIONSHIPS FIRST</span><h2>Kenali pelanggan.<br>Temukan peluang.<br><span>Tumbuh bersama.</span></h2><p>CRM membantu Anda mengelola hubungan pelanggan: siapa mereka, apa yang mereka butuhkan, dan kapan Anda perlu menghubungi mereka kembali.</p><a class="btn primary" href="#leads">Mulai dari lead pertama ${icon('arrow')}</a><div class="guide-graphic" aria-hidden="true"><span>${icon('people')}</span><span>${icon('target')}</span><span>${icon('board')}</span></div></section><div class="guide-grid">${[['01','Lead','Calon pelanggan yang baru menunjukkan minat. Catat sumber dan kebutuhannya sebelum menilai kecocokan.','leads'],['02','Contact & Company','Contact adalah orang yang Anda hubungi; company adalah perusahaan tempat ia bekerja. Di demo ini, perusahaan dicatat pada kontak.','contacts'],['03','Deal & Pipeline','Deal adalah peluang penjualan dengan nilai dan target tanggal. Pipeline menunjukkan kemajuannya dari baru sampai berhasil atau gagal.','pipeline'],['04','Activity & Follow-up','Catat langkah berikutnya sebagai tugas. Follow-up menjaga komunikasi dan membantu peluang terus bergerak.','tasks']].map(([n,t,d,p])=>`<section class="panel guide-card"><span class="guide-number">${n}</span><h3>${t}</h3><p>${d}</p><a href="#${p}" class="text-link">Coba sekarang ${icon('arrow')}</a></section>`).join('')}</div><section class="panel walkthrough"><h2>Coba satu alur CRM lengkap</h2><ol><li>Tambahkan lead dari perusahaan yang tertarik membuat website.</li><li>Ubah status menjadi Kualifikasi setelah kebutuhan dan anggarannya jelas.</li><li>Klik Konversi dan isi nilai deal sebelum menyimpan; server membuat perusahaan, kontak, dan optional deal dalam satu transaksi.</li><li>Isi nilai penawaran dan gerakkan deal lewat Proposal serta Negosiasi.</li><li>Buat tugas follow-up, lalu tandai deal Berhasil ketika kontrak disepakati.</li></ol><p class="muted">Win rate = deal berhasil ÷ seluruh deal yang ditutup pada periode pilihan. Nilai deal berhasil tidak berarti uang sudah diterima.</p></section>`;}
function settingsPage(){const admin=data.user.role==='admin';return `<div class="settings-grid"><section class="panel settings-panel"><h2>Workspace Anda</h2><p class="muted">Konfigurasi bersama dikelola oleh Admin.</p><form id="workspace-form"><label>Nama workspace<input name="workspace" value="${esc(data.workspace)}" required maxlength="80" ${admin?'':'disabled'}></label><label>Batas At Risk (hari)<input name="risk_days" type="number" min="1" max="365" value="${data.risk_days}" ${admin?'':'disabled'}></label>${admin?'<button class="btn primary" type="submit">Simpan perubahan</button>':''}</form><div class="storage-note">${icon('shield')}<div><strong>Backend PostgreSQL</strong><p>Anda masuk sebagai ${esc(roleLabel(data.user.role))}. Server memeriksa ownership dan role. Riwayat audit tidak dapat diedit atau dihapus melalui aplikasi.</p></div></div></section><section class="panel settings-panel"><h2>Data & backup</h2><p class="muted">Ekspor hanya data yang dapat Anda akses.</p><div class="setting-action"><div><strong>Ekspor backup</strong><small>JSON data CRM dan audit untuk inspeksi.</small></div><button class="btn" data-action="backup">${icon('download')}Ekspor</button></div>${admin?`<div class="setting-action"><div><strong>Impor data</strong><small>Tambahkan record sebagai milik Admin; tidak mengganti audit. Konversi direkonstruksi server; audit lama hanya untuk inspeksi.</small></div><button class="btn" data-action="import">Impor JSON</button><input type="file" id="import-file" accept=".json,application/json" hidden></div><div class="setting-action"><div><strong>Reset data fiktif</strong><small>Hanya di lingkungan demo yang mengizinkan reset. Audit tetap tersimpan.</small></div><button class="btn danger" data-action="reset">Reset demo</button></div>`:'<p class="muted">Impor/reset hanya tersedia untuk Admin.</p>'}</section></div><div class="info-strip">${icon('book')}<span>Demo portfolio menggunakan data fiktif. Tidak ada integrasi AI, pembayaran, email, atau WhatsApp.</span></div>`;}
function companiesPage(){const list=data.companies.filter(c=>matches(c.name));return `${toolbar(null)}<section class="panel"><div class="panel-heading"><h2>Perusahaan <span class="count-label">${list.length}</span></h2></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>PERUSAHAAN</th><th>KONTAK</th><th>PELUANG</th><th>OWNER</th><th></th></tr></thead><tbody>${list.map(c=>`<tr><td><button class="row-person" data-action="edit" data-kind="companies" data-id="${esc(c.id)}"><strong>${esc(c.name)}</strong></button></td><td>${data.contacts.filter(r=>r.company_id===c.id).length}</td><td>${data.deals.filter(r=>r.company_id===c.id).length}</td><td>${esc(data.users.find(u=>u.id===c.owner_id)?.name||'Assigned record')}</td><td><button class="icon-btn" data-action="edit" data-kind="companies" data-id="${esc(c.id)}" aria-label="Edit ${esc(c.name)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada perusahaan','Tambahkan akun bisnis pertama Anda.',actionButton('companies','Tambah perusahaan'))}</section>`;}
function usersPage(){return `<section class="panel"><div class="panel-heading"><h2>Pengguna workspace</h2><p>Perubahan role/status membatalkan sesi aktif pengguna.</p></div><div class="table-wrap"><table><thead><tr><th>NAMA</th><th>EMAIL</th><th>ROLE</th><th>TIM</th><th>STATUS</th><th></th></tr></thead><tbody>${data.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(roleLabel(u.role))}</td><td>${esc(u.team)}</td><td>${u.active?'Aktif':'Nonaktif'}</td><td><button class="btn small" data-action="user-edit" data-id="${esc(u.id)}">Edit akses</button></td></tr>`).join('')}</tbody></table></div></section>`;}

function navigate(p){if(location.hash==='#'+p){page=p;query='';filter='Semua';mobile=false;render();}else location.hash=p;}
window.addEventListener('hashchange',()=>{if(!data)return;page=location.hash.slice(1);query='';filter='Semua';mobile=false;render();window.scrollTo(0,0);});
function bindPage(){
  $('#period')?.addEventListener('change',async e=>{days=Number(e.target.value);$('#page-content').setAttribute('aria-busy','true');try{await refresh();}catch(error){toast(error.message);}finally{$('#page-content')?.removeAttribute('aria-busy');}});
  $('#search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();try{$('#search').setSelectionRange(pos,pos);}catch{/* Search inputs may not support selection ranges. */}});
  $('#filter')?.addEventListener('change',e=>{filter=e.target.value;render();});
  document.querySelectorAll('[data-task]').forEach(el=>el.addEventListener('change',()=>{const t=data.tasks.find(t=>t.id===el.dataset.task);mutate(()=>request(`/tasks/${t.id}?revision=${t.revision}`,{method:'PUT',body:recordPayload('tasks',{...t,done:el.checked})}),'Status tugas diperbarui.');}));
  document.querySelectorAll('[data-move]').forEach(el=>el.addEventListener('change',()=>changeStage(el.dataset.move,el.value)));
  document.querySelectorAll('[draggable]').forEach(el=>el.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain',el.dataset.deal);e.dataTransfer.effectAllowed='move';}));
  document.querySelectorAll('[data-stage].kanban-column').forEach(el=>{el.addEventListener('dragover',e=>{e.preventDefault();el.classList.add('drag-over');});el.addEventListener('dragleave',()=>el.classList.remove('drag-over'));el.addEventListener('drop',e=>{e.preventDefault();el.classList.remove('drag-over');changeStage(e.dataTransfer.getData('text/plain'),el.dataset.stage);});});
  $('#workspace-form')?.addEventListener('submit',e=>{e.preventDefault();const form=Object.fromEntries(new FormData(e.target));mutate(()=>request('/config',{method:'PUT',body:{workspace:form.workspace.trim(),risk_days:Number(form.risk_days)}}),'Konfigurasi diperbarui.');});
  $('#import-file')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>5e6){toast('Backup maksimal 5 MB.');return;}try{const payload=JSON.parse(await file.text());confirmModal('Impor data ke server?','Record akan ditambahkan sebagai milik Admin. Seluruh impor dibatalkan jika ada data tidak valid.',()=>mutate(()=>request('/backup/import',{method:'POST',body:payload}),'Data berhasil diimpor.'));}catch{toast('File JSON tidak valid.');}});
}
function changeStage(id,stage){const deal=data.deals.find(d=>d.id===id);if(!deal)return;const privileged=!([deal.owner_id,deal.assigned_id].includes(data.user.id));const submit=(closing_reason='',change_reason='')=>mutate(()=>request(`/opportunities/${id}/stage`,{method:'POST',body:{stage:stageCode(stage),revision:deal.revision,closing_reason,change_reason}}),`Deal dipindahkan ke ${stage}.`);
  if(stage==='Gagal'||privileged){render();$('#modal').innerHTML=`<div class="modal-heading"><h2 id="modal-title">Pindahkan ke ${esc(stage)}</h2><button class="icon-btn" data-action="close" aria-label="Tutup">${icon('close')}</button></div><form id="stage-form"><label>Alasan perubahan<textarea name="reason" required maxlength="2000" rows="3"></textarea></label><div class="modal-actions"><button type="button" class="btn" data-action="close">Batal</button><button type="submit" class="btn primary">Simpan tahap</button></div></form>`;$('#modal').showModal();$('#stage-form').onsubmit=e=>{e.preventDefault();const reason=new FormData(e.target).get('reason').trim();submit(stage==='Gagal'?reason:'',privileged?reason:'');};}else submit();
}
document.addEventListener('click',e=>{const demo=e.target.closest('[data-demo-email]');if(demo){$('#login-form [name="email"]').value=demo.dataset.demoEmail;$('#login-form [name="password"]').value='PortfolioDemo!2026';return;}const el=e.target.closest('[data-action]');if(!el)return;const {action,kind,id}=el.dataset;
  if(action==='new')kind==='users'?userForm():openForm(kind,null,{stage:el.dataset.stage});
  if(action==='edit')openForm(kind,id);
  if(action==='user-edit')userForm(id);
  if(action==='owner')ownerForm(kind,id);
  if(action==='followup')followupForm(kind,id);
  if(action==='audit')auditDetails(id);
  if(action==='navigate')navigate(el.dataset.page);
  if(action==='menu'){mobile=!mobile;render();if(mobile)$('.sidebar .nav-item.active')?.focus();else $('.mobile-toggle')?.focus();}
  if(action==='task-filter'){taskFilter=el.dataset.filter;render();}
  if(action==='close')$('#modal').close();
  if(action==='delete')deleteItem(kind,id);
  if(action==='convert')convertLead(id);
  if(action==='csv')exportCsv();
  if(action==='backup')request('/backup').then(result=>download('crm-business-backup-v2.json',JSON.stringify(result,null,2),'application/json')).catch(error=>toast(error.message));
  if(action==='import')$('#import-file').click();
  if(action==='reset')confirmModal('Reset data fiktif bersama?','Data demo seluruh pengguna demo akan diganti. Audit tetap tersimpan; record pengguna non-demo tidak dihapus.',()=>mutate(()=>request('/demo/reset',{method:'POST'}),'Data demo dipulihkan.'));
  if(action==='logout')request('/auth/logout',{method:'POST'}).then(()=>{$('#modal').close();showLogin();}).catch(error=>toast(error.message));
});
const names={companies:'perusahaan',contacts:'kontak',leads:'lead',deals:'deal',tasks:'tugas'};
function input(label,name,value='',type='text',required=false,extra=''){return `<label>${label}${required?' <span class="required">*</span>':''}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra} maxlength="200"></label>`;}
function select(label,name,options,value,required=false){return `<label>${label}${required?' <span class="required">*</span>':''}<select name="${name}" ${required?'required':''}>${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;}
function openForm(kind,id=null,defaults={}){
  const item=id?data[kind].find(r=>r.id===id):{};if(!item)return;const v={...defaults,...item};let fields='';
  if(kind==='companies')fields=input('Nama perusahaan','name',v.name,'text',true);
  if(kind==='contacts')fields=input('Nama lengkap','name',v.name,'text',true)+input('Perusahaan','company',v.company,'text',true)+input('Email','email',v.email,'email')+input('Telepon','phone',v.phone,'tel')+input('Jabatan','role',v.role);
  if(kind==='leads')fields=input('Nama lengkap','name',v.name,'text',true)+input('Perusahaan','company',v.company,'text',true)+input('Email','email',v.email,'email')+select('Sumber lead','source',['Website','Instagram','LinkedIn','Referral','Event','Lainnya'],v.source||'Website')+select('Status','status',['Baru','Dihubungi','Kualifikasi','Tidak cocok'],v.status||'Baru')+`<label class="full">Kebutuhan / catatan<textarea name="notes" rows="3" maxlength="5000">${esc(v.notes)}</textarea></label>`;
  if(kind==='deals')fields=input('Nama peluang','title',v.title,'text',true)+select('Kontak terkait','contact',[['','Pilih kontak'],...data.contacts.map(c=>[c.id,`${c.name} · ${c.company}`])],v.contact||'',true)+input('Nilai penawaran (Rp)','value',v.value??'','number',true,'min="0" max="1000000000000" step="0.01"')+select('Tahap','stage',STAGES,v.stage||'Baru')+input('Target penutupan','due',v.due||offsetDate(14),'date',true)+input('Alasan Gagal (wajib jika Gagal)','closing_reason',v.closing_reason)+input('Alasan perubahan (Manager/Admin)','change_reason','')+`<label class="full">Catatan deal<textarea name="notes" rows="3" maxlength="5000">${esc(v.notes)}</textarea></label>`;
  if(kind==='tasks')fields=input('Judul tugas','title',v.title,'text',true)+select('Kontak terkait','contact',[['','Tanpa kontak'],...data.contacts.map(c=>[c.id,`${c.name} · ${c.company}`])],v.contact||'')+select('Lead terkait','lead_id',[['','Tanpa lead'],...data.leads.map(l=>[l.id,l.name])],v.lead_id||'')+select('Opportunity terkait','opportunity_id',[['','Tanpa opportunity'],...data.deals.map(d=>[d.id,d.title])],v.opportunity_id||'')+input('Tanggal follow-up','date',v.date||dateKey(),'date',true)+select('Prioritas','priority',['Rendah','Sedang','Tinggi'],v.priority||'Sedang');
  if(!id&&data.user.role!=='sales')fields+=select('Owner','owner_id',data.users.filter(u=>u.active).map(u=>[u.id,u.name]),data.user.id,true);
  const immutable=kind==='leads'&&v.status==='Dikonversi';
  $('#modal').innerHTML=`<div class="modal-heading"><div><span class="eyebrow">YOUR NEXT CONNECTION</span><h2 id="modal-title">${id?'Edit':'Tambah'} ${names[kind]}</h2></div><button class="icon-btn" data-action="close" aria-label="Tutup formulir">${icon('close')}</button></div><form id="record-form"><div class="form-grid">${fields}</div><p class="form-help">${immutable?'Lead sudah dikonversi. Edit kontak atau deal terkait.':'* Wajib diisi. Perubahan divalidasi dan disimpan di server.'}</p><div class="record-commands">${id&&data.user.role!=='sales'?`<button type="button" class="btn small" data-action="owner" data-kind="${kind}" data-id="${esc(id)}">Owner / assignee</button>`:''}${id&&['deals','leads','contacts'].includes(kind)?`<button type="button" class="btn small" data-action="followup" data-kind="${kind}" data-id="${esc(id)}">Catat follow-up</button>`:''}</div><div class="modal-actions">${id&&kind!=='deals'&&!immutable?`<button type="button" class="btn danger delete-button" data-action="delete" data-kind="${kind}" data-id="${esc(id)}">${icon('trash')}Hapus</button>`:''}<button type="button" class="btn" data-action="close">Batal</button>${immutable?'':`<button class="btn primary" type="submit">${id?'Simpan perubahan':`Tambah ${names[kind]}`}</button>`}</div></form>`;
  if(!$('#modal').open)$('#modal').showModal();
  $('#record-form').onsubmit=e=>{e.preventDefault();if(immutable)return;const values=Object.fromEntries(new FormData(e.target));if(kind==='tasks')values.done=v.done||false;const url=`/${resource(kind)}${id?`/${id}?revision=${v.revision}`:''}`;mutate(()=>request(url,{method:id?'PUT':'POST',body:recordPayload(kind,values)}),`${names[kind]} berhasil disimpan.`);};
}
function confirmModal(title,text,callback){$('#modal').innerHTML=`<div class="modal-heading"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="Tutup">${icon('close')}</button></div><p class="confirm-text">${esc(text)}</p><div class="modal-actions"><button class="btn" data-action="close">Batal</button><button id="confirm" class="btn primary">Lanjutkan</button></div>`;if(!$('#modal').open)$('#modal').showModal();$('#confirm').onclick=callback;}
function deleteItem(kind,id){const item=data[kind].find(r=>r.id===id);confirmModal(`Hapus ${names[kind]}?`,'Record terkait tidak dapat dihapus. Server tetap menyimpan audit tindakan ini.',()=>mutate(()=>request(`/${resource(kind)}/${id}?revision=${item.revision}`,{method:'DELETE'}),'Data dihapus.'));}
function convertLead(id){const lead=data.leads.find(l=>l.id===id);if(!lead||lead.status==='Dikonversi')return;$('#modal').innerHTML=`<div class="modal-heading"><h2 id="modal-title">Konversikan lead</h2><button class="icon-btn" data-action="close" aria-label="Tutup">${icon('close')}</button></div><p class="form-help">Perusahaan, kontak, dan optional deal dibuat dalam satu transaksi. Jika gagal, seluruh perubahan dibatalkan.</p><form id="conversion-form"><div class="form-grid">${select('Buat opportunity','create_opportunity',[['yes','Ya, buat deal'],['no','Hanya perusahaan & kontak']],'yes')}${input('Nama peluang','title',`Website ${lead.company}`)}${input('Nilai penawaran (Rp)','value',0,'number',false,'min="0" max="1000000000000" step="0.01"')}${input('Target penutupan','due',offsetDate(14),'date')}</div><div class="modal-actions"><button type="button" class="btn" data-action="close">Batal</button><button class="btn primary" type="submit">Konversi lead</button></div></form>`;if(!$('#modal').open)$('#modal').showModal();$('#conversion-form').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));mutate(()=>request(`/leads/${id}/convert`,{method:'POST',body:{revision:lead.revision,create_opportunity:v.create_opportunity==='yes',title:v.title,value:v.value||'0',due:v.due||null}}),'Lead berhasil dikonversi dalam satu transaksi.');};}
function ownerForm(kind,id){const record=data[kind].find(r=>r.id===id);$('#modal').innerHTML=`<div class="modal-heading"><h2 id="modal-title">Owner & assignee</h2><button class="icon-btn" data-action="close" aria-label="Tutup">${icon('close')}</button></div><form id="owner-form"><div class="form-grid">${select('Owner','owner_id',data.users.filter(u=>u.active).map(u=>[u.id,u.name]),record.owner_id,true)}${select('Assignee','assigned_id',[['','Tidak ditugaskan'],...data.users.filter(u=>u.active).map(u=>[u.id,u.name])],record.assigned_id||'')}${input('Alasan perubahan','reason','','text',true)}</div><p class="form-help">Owner perusahaan/kontak tetap untuk konsistensi deduplikasi. Berikan assignee untuk kolaborasi. Owner deal baru harus memiliki akses kontak/perusahaan terkait.</p><div class="modal-actions"><button type="button" class="btn" data-action="close">Batal</button><button type="submit" class="btn primary">Simpan assignment</button></div></form>`;$('#owner-form').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));mutate(()=>request(`/${resource(kind)}/${id}/owner`,{method:'POST',body:{...v,assigned_id:v.assigned_id||null,revision:record.revision}}),'Assignment dicatat dalam audit.');};}
function followupForm(kind,id){$('#modal').innerHTML=`<div class="modal-heading"><h2 id="modal-title">Catat follow-up</h2><button class="icon-btn" data-action="close" aria-label="Tutup">${icon('close')}</button></div><form id="followup-form"><label>Catatan interaksi<textarea name="note" rows="4" required maxlength="5000"></textarea></label><div class="modal-actions"><button type="button" class="btn" data-action="close">Batal</button><button type="submit" class="btn primary">Simpan follow-up</button></div></form>`;$('#followup-form').onsubmit=e=>{e.preventDefault();const note=new FormData(e.target).get('note');mutate(()=>request('/activities',{method:'POST',body:{entity_type:resource(kind),entity_id:id,note}}),'Follow-up dicatat dalam audit.');};}
function userForm(id=null){const user=id?data.users.find(u=>u.id===id):{};$('#modal').innerHTML=`<div class="modal-heading"><h2 id="modal-title">${id?'Edit akses':'Tambah pengguna'}</h2><button class="icon-btn" data-action="close" aria-label="Tutup">${icon('close')}</button></div><form id="user-form"><div class="form-grid">${input('Nama','name',user.name,'text',true)}${id?'':input('Email','email','','email',true)}${input('Password '+(id?'(kosong = tetap)':'(min. 12 karakter)'),'password','','password',!id,'minlength="12" autocomplete="new-password"')}${select('Role','role',[['sales','Sales Representative'],['manager','Sales Manager'],['admin','Admin']],user.role||'sales')}${input('Tim','team',user.team||data.user.team,'text',true)}${id?select('Status','active',[['true','Aktif'],['false','Nonaktif']],String(user.active)):''}</div><div class="modal-actions"><button type="button" class="btn" data-action="close">Batal</button><button type="submit" class="btn primary">Simpan pengguna</button></div></form>`;if(!$('#modal').open)$('#modal').showModal();$('#user-form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));if(id){values.active=values.active==='true';if(!values.password)delete values.password;}mutate(()=>request(`/users${id?'/'+id:''}`,{method:id?'PATCH':'POST',body:values}),'Pengguna diperbarui.');};}
function auditDetails(id){const event=data.activities.find(a=>a.id===id);if(!event)return;$('#modal').innerHTML=`<div class="modal-heading"><h2 id="modal-title">Detail audit</h2><button class="icon-btn" data-action="close" aria-label="Tutup">${icon('close')}</button></div><p class="form-help">${esc(event.actor)} · ${esc(event.action)} · ${esc(event.date)}<br>${esc(event.entity_type)} / ${esc(event.entity_id)}</p>${[['Sebelum',event.old_value],['Sesudah',event.new_value],['Metadata / alasan',event.metadata]].map(([label,value])=>`<h3 class="audit-heading">${label}</h3><pre class="audit-json">${esc(JSON.stringify(value,null,2))}</pre>`).join('')}<p class="form-help">Riwayat ini hanya dapat dibaca dan dilindungi oleh PostgreSQL.</p>`;if(!$('#modal').open)$('#modal').showModal();}

function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('File ekspor telah disiapkan.');}
function exportCsv(){const cell=s=>{let v=String(s??'');if(/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"';};const rows=[['Nama','Perusahaan','Email','Telepon','Jabatan'],...data.contacts.filter(c=>matches(c.name,c.company,c.email)).map(c=>[c.name,c.company,c.email,c.phone,c.role])];download('crm-business-kontak.csv','\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
bootstrap();
